<x-capstone::dialog id="new-bid" title="Kirim Bid Baru" width="max-w-[520px]" description="Pilih judul untuk di-bid. Pembimbing ditetapkan saat finalisasi (penyeimbangan)."><p class="text-sm mt-2"><span class="font-medium" x-text="Math.max(0,3-total)+' slot tersisa'"></span> (max 3 bids + proposals combined).</p><form @submit.prevent="save()"><div class="grid gap-4 py-4"><x-alert style="danger" x-show="errors.root"><span x-text="errors.root"></span></x-alert><label class="grid gap-2 text-sm font-medium" for="bid-title">Judul <x-capstone::select-menu x-model="form.title_id" :options="[]" placeholder="Pilih judul..." aria-label="Pilih..."><template x-for="title in availableTitles" :key="title.id"><button type="button" role="option" @click="pick(String(title.id), title.title)" :aria-selected="(String(selectedValue) === String(String(title.id))).toString()" class="flex w-full items-center justify-between gap-2 rounded-radius px-2 py-1.5 text-sm hover:bg-surface-alt" :class="String(selectedValue) === String(String(title.id)) ? 'bg-primary/10 font-medium' : ''"><span class="truncate" x-text="title.title"></span><span x-show="String(selectedValue) === String(String(title.id))" class="text-primary"><x-capstone::icon name="Check" size="14" /></span></button></template></x-capstone::select-menu></label>
</div><div class="flex justify-end gap-2"><x-btn style="outline" @click="close('new-bid')">Batal</x-btn><x-btn type="submit" x-bind:disabled="saving || !canSubmit">Kirim Bid</x-btn></div></form></x-capstone::dialog>
